package edu.ankara.audiometer.ui.view;
import edu.ankara.audiometer.domain.model.ThresholdCriterion;import javafx.scene.control.*;import javafx.scene.layout.*;import java.util.function.Consumer;
public final class ControlPanel extends TitledPane { public ControlPanel(Runnable start,Runnable present,Runnable response,Runnable autoSim,Runnable reset,Consumer<ThresholdCriterion> criterion){ setText("Test Control & Simulation"); setCollapsible(false); ComboBox<String> ear=new ComboBox<>(); ear.getItems().addAll("Both","Right","Left"); ear.setValue("Both"); ComboBox<String> mode=new ComboBox<>(); mode.getItems().addAll("Automatic Hughson-Westlake","Manual"); mode.setValue("Automatic Hughson-Westlake"); ComboBox<ThresholdCriterion> crit=new ComboBox<>(); crit.getItems().addAll(ThresholdCriterion.values()); crit.setValue(ThresholdCriterion.TWO_OUT_OF_THREE_ASCENDING); crit.setOnAction(e->criterion.accept(crit.getValue())); Button bStart=new Button("Start test"); bStart.setOnAction(e->start.run()); Button bPause=new Button("Pause test"); Button bStop=new Button("Stop test"); Button bReset=new Button("Reset test"); bReset.setOnAction(e->reset.run()); Button bPresent=new Button("Present tone"); bPresent.setOnAction(e->present.run()); Button bResp=new Button("Mark RESPONSE"); bResp.getStyleClass().add("response"); bResp.setOnAction(e->response.run()); Button bAuto=new Button("Auto simulate step"); bAuto.setOnAction(e->autoSim.run()); GridPane g=new GridPane(); g.setHgap(6); g.setVgap(8); g.addRow(0,new Label("Ear"),ear); g.addRow(1,new Label("Mode"),mode); g.addRow(2,new Label("Criterion"),crit); FlowPane buttons=new FlowPane(6,6,bStart,bPause,bStop,bReset,bPresent,bResp,bAuto); setContent(new VBox(10,g,buttons,new Label("Simulation threshold defaults: RIGHT 25 dB HL, LEFT 30 dB HL."))); } }
